// Configure somente este token e use o mesmo valor em
// ATENDIMENTO_MANUAL_WEBHOOK_TOKEN no serviço do painel.
const EXPECTED_TOKEN = 'COLE_O_MESMO_TOKEN_DO_PAINEL';

const payload = $json.body ?? $json;
const expected = String(EXPECTED_TOKEN || '').trim();
const received = String(payload.token || '').trim();

if (!expected || expected === 'COLE_O_MESMO_TOKEN_DO_PAINEL') {
  throw new Error('Configure EXPECTED_TOKEN neste node.');
}
if (!received || received !== expected) {
  throw new Error('Token inválido para o webhook de atendimento manual.');
}

const candidatoId = Number(payload.candidato_id);
if (!Number.isInteger(candidatoId) || candidatoId <= 0) {
  throw new Error('candidato_id inválido.');
}
const mensagem = String(payload.mensagem || '').trim();
if (!mensagem) throw new Error('A mensagem não pode ficar vazia.');
if (mensagem.length > 4000) throw new Error('A mensagem excede 4.000 caracteres.');

return [{json:{
  candidato_id:candidatoId,
  mensagem,
  evento:String(payload.evento || 'MENSAGEM_MANUAL_ENVIADA').trim().slice(0,120),
  solicitado_por:String(payload.solicitado_por || 'Recrutador').trim().slice(0,200),
  session:String(payload.session || 'whats_junior').trim()
}}];

const c = $input.first().json ?? {};
if (!c.candidato_id) throw new Error('Candidato não encontrado.');
const telefone = String(c.telefone || '').replace(/\D/g, '');
if (!/^55\d{10,11}$/.test(telefone)) throw new Error('Telefone do candidato inválido.');
return [{json:{
  ...c,
  telefone,
  chatId:`${telefone}@c.us`,
  text:String(c.mensagem || '').trim()
}}];
